  @ffi.Float()
  external double fill_percentage;

  @ffi.Int32()
  external int is_buffering;

  @ffi.Int32()
  external int is_eof;

  @ffi.Int64()
  external int read_cursor_byte;

  @ffi.Int64()
  external int range_start;

  @ffi.Int64()
